'use strict';

// MODULES //

var join = require( 'path' ).join;
var tape = require( 'tape' );
var RuleTester = require( 'eslint' ).RuleTester;
var parser = require( 'yaml-eslint-parser' );
var readFile = require( '@stdlib/fs/read-file' ).sync;
var rule = require( './../lib' );


// VARIABLES //

var RE_COPYRIGHT = /^# Copyright.*$/m;


// FIXTURES //

var valid = readFile( join( __dirname, 'fixtures', 'valid.yml' ), 'utf8' );
var invalid = readFile( join( __dirname, 'fixtures', 'invalid.yml.txt' ), 'utf8' );


// TESTS //

tape( 'main export is an object', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof rule, 'object', 'main export is an object' );
	t.end();
});

tape( 'the export has a `create` method', function test( t ) {
	t.strictEqual( typeof rule.create, 'function', 'has a create method' );
	t.end();
});

tape( 'the export has a `meta` property', function test( t ) {
	t.strictEqual( typeof rule.meta, 'object', 'has a meta property' );
	t.end();
});

tape( 'the rule validates YAML license headers and copyright notices', function test( t ) {
	var tester = new RuleTester({
		'languageOptions': {
			'parser': parser
		}
	});

	try {
		tester.run( 'yaml-license-header', rule, {
			'valid': [
				valid,
				valid.replace( RE_COPYRIGHT, '# Copyright (c) 2017 The Stdlib Authors.' )
			],
			'invalid': [
				{
					'code': invalid,
					'errors': [{
						'message': 'YAML files must start with the Apache-2.0 license header.',
						'line': 1
					}]
				},
				{
					'code': valid.replace( RE_COPYRIGHT, '# Copyright (c) nonsense' ),
					'errors': [{
						'message': 'Missing or malformed copyright line in license header.',
						'line': 4
					}]
				},
				{
					'code': valid.replace( RE_COPYRIGHT, '# Copyright (c) The Stdlib Authors.' ),
					'errors': [{
						'message': 'Missing or malformed copyright line in license header.',
						'line': 4
					}]
				},
				{
					'code': valid.replace( RE_COPYRIGHT, '# Copyright (c) 26 The Stdlib Authors.' ),
					'errors': [{
						'message': 'Missing or malformed copyright line in license header.',
						'line': 4
					}]
				},
				{
					'code': valid.replace( 'The Stdlib Authors.', 'Someone Else.' ),
					'errors': [{
						'message': 'Missing or malformed copyright line in license header.',
						'line': 4
					}]
				},
				{
					'code': valid.replace( '# @license Apache-2.0', '# @license MIT' ),
					'errors': [{
						'message': 'YAML files must start with the Apache-2.0 license header. Expected "# @license Apache-2.0" on line 2.',
						'line': 2
					}]
				},
				{
					'code': '\n' + valid,
					'errors': [{
						'message': 'YAML files must start with the Apache-2.0 license header. Expected "#/" on line 1.',
						'line': 1
					}]
				}
			]
		});
		t.pass( 'passed without errors' );
	} catch ( err ) {
		t.fail( 'encountered an error: ' + err.message );
	}
	t.end();
});
